const infoContent=new Map();
function pager(key,p){return `<nav class="pager" aria-label="${esc(key)} 페이지"><button data-page="${esc(key)}" data-index="${p.page-1}" ${p.page===0?'disabled':''} aria-label="이전 페이지">‹ 이전</button><span aria-live="polite">${p.page+1} / ${p.pages}<small> · ${p.total}건</small></span><button data-page="${esc(key)}" data-index="${p.page+1}" ${p.page===p.pages-1?'disabled':''} aria-label="다음 페이지">다음 ›</button></nav>`;}
function pageList(items,key,itemHTML,rowHeight=110,emptyText='표시할 항목이 없습니다.'){
 const p=paginate(items,state.pages[key],state.pageSizes[key]||1);state.pages[key]=p.page;
 return `<div class="page-list" data-fit="${esc(key)}" data-row-height="${rowHeight}" style="--row-height:${rowHeight}px">${p.items.map(itemHTML).join('')||empty(esc(emptyText))}</div>${pager(key,p)}`;
}
function bindPaging(root=app){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.pages[b.dataset.page]=+b.dataset.index;render();});pageObserver?.disconnect();pageObserver=new ResizeObserver(entries=>{let changed=false;for(const {target,contentRect} of entries){if(contentRect.height<1)continue;const key=target.dataset.fit,size=Math.max(1,Math.floor((contentRect.height+1)/+target.dataset.rowHeight));if(state.pageSizes[key]!==size){state.pageSizes[key]=size;changed=true;}}if(changed){clearTimeout(fitTimer);fitTimer=setTimeout(render,0);}});root.querySelectorAll('[data-fit]').forEach(n=>pageObserver.observe(n));}
function infoButton(key,title,body,label='자세히 보기'){infoContent.set(key,{title,body});return `<button class="text-btn" data-info="${esc(key)}">${esc(label)} →</button>`;}
function showInfo(key){const info=infoContent.get(key);if(!info)return;$('#historyDetail').innerHTML=`<div class="dialog-head"><h2>${esc(info.title)}</h2><button class="icon-btn" id="closeHistory" aria-label="닫기">×</button></div><div class="dialog-body info-body">${esc(info.body)}</div>`;$('#closeHistory').onclick=()=>$('#historyDetail').close();$('#historyDetail').showModal();}

let channel,loadSeq=0,toastTimer,reloadTimer,searchTimer,starting=false,editTask=null,detailHistory=[];
let conversationTarget={task_id:null,event_id:null},threadPage=0,detailPage=0;
const drafts=new Map();
const targetKey=t=>t.task_id?'task:'+t.task_id:t.event_id?'event:'+t.event_id:'general';
const statusBadge=s=>`<span class="badge ${esc(s)}">${esc(statuses[s]||s)}</span>`;
const empty=(s)=>`<div class="empty"><span class="large">◌</span>${s}</div>`;
const link=(url,label,cls='')=>safeURL(url)?`<a class="${cls}" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:`<span class="muted">${esc(label)} · 직접 링크 미확인</span>`;
const options=(values,current)=>Object.entries(values).map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('');
async function loadFiles(){try{const [files,runs]=await Promise.all([rows('file_changes',q=>q.eq('workspace_id',state.workspace.id).gte('changed_at',addDays(day(),-6)+'T00:00:00+09:00').order('changed_at',{ascending:false}).order('id',{ascending:false})),db.from('file_sync_runs').select('*').eq('workspace_id',state.workspace.id).order('checked_at',{ascending:false}).limit(5)]);if(runs.error)throw runs.error;state.files=files;state.fileRuns=runs.data;state.fileError='';}catch{state.fileError='최근 파일 확인에 연결하지 못했습니다. 이전 목록을 유지합니다.';}}
function weatherWidget(){
 const city=WEATHER_CITIES[state.weatherCity],cached=state.weather[city.id],w=cached?.days?.[0]?.date===day()?cached:null,error=state.weatherErrors[city.id];
 const header=`<div class="weather-heading"><span aria-live="polite">${city.name} 날씨</span><div class="weather-controls"><button data-city="0" class="${state.weatherCity===0?'selected':''}" aria-pressed="${state.weatherCity===0}">천안</button><button data-city="1" class="${state.weatherCity===1?'selected':''}" aria-pressed="${state.weatherCity===1}">서울</button><button data-city="${1-state.weatherCity}" aria-label="다음 지역 날씨">›</button></div></div>`;
 if(!w)return `${header}<div class="weather-empty">${error?'날씨를 불러오지 못했습니다.':'오늘·내일 예보를 확인하고 있습니다…'}${error?'<button class="text-btn" id="weatherRetry">다시 확인</button>':''}</div><div class="weather-credit"><span>${state.weatherCity+1} / 2 · 옆으로 넘겨보세요</span><a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a></div>`;
 const today=w.days[0],tomorrow=w.days[1],now=weatherDescription(w.current?.code??today.code,w.current?.isDay??true),next=weatherDescription(tomorrow.code);
 return `${header}<div class="weather-content"><div class="weather-now"><span class="weather-symbol" aria-hidden="true">${now.icon}</span><div><strong>${degrees(w.current?.temperature)}</strong><span>오늘 · ${now.label}</span></div><div class="weather-range"><span>최고 ${degrees(today.max)}</span><span>최저 ${degrees(today.min)}</span></div></div><div class="weather-tomorrow"><span><span aria-hidden="true">${next.icon}</span> 내일 · ${next.label}</span><b>${degrees(tomorrow.min)} / ${degrees(tomorrow.max)}</b><small>강수 ${tomorrow.rain===null?'—':Math.round(tomorrow.rain)+'%'}</small></div></div><div class="weather-credit"><span>${state.weatherCity+1} / 2 · ${error?'이전 예보':kstTime(w.fetchedAt)}</span><a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo ↗</a></div>`;
}
function bindWeather(){const widget=$('#weatherWidget');if(!widget)return;widget.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>{state.weatherCity=+b.dataset.city;widget.innerHTML=weatherWidget();bindWeather();});if($('#weatherRetry'))$('#weatherRetry').onclick=()=>updateWeather(true);let start;widget.onpointerdown=e=>{start={x:e.clientX,y:e.clientY};if(!e.target.closest('button,a'))widget.setPointerCapture(e.pointerId);};widget.onpointercancel=()=>{start=null;};widget.onpointerup=e=>{if(start&&Math.abs(e.clientX-start.x)>40&&Math.abs(e.clientY-start.y)<50){state.weatherCity=1-state.weatherCity;widget.innerHTML=weatherWidget();bindWeather();}start=null;};}
async function updateWeather(force=false){
 const dateChanged=Object.values(state.weather).some(w=>w.days[0].date!==day());
 if(!state.workspace||state.weatherBusy||(!force&&!dateChanged&&Date.now()-weatherAttempt<1800000))return;
 weatherAttempt=Date.now();state.weatherBusy=true;
 const results=await Promise.allSettled(WEATHER_CITIES.map(c=>fetchWeather(fetch,new Date(),c.id)));
 results.forEach((r,i)=>{const id=WEATHER_CITIES[i].id;if(r.status==='fulfilled'){state.weather[id]=r.value;delete state.weatherErrors[id];}else state.weatherErrors[id]=r.reason?.message||'연결 실패';});
 state.weatherBusy=false;const widget=$('#weatherWidget');if(widget){widget.innerHTML=weatherWidget();bindWeather();}
}
async function loadFileSummaries(){
 try{state.fileSummaries=await rows('file_summaries',q=>q.eq('workspace_id',state.workspace.id).order('item_id'));state.summaryError='';}
 catch{state.summaryError='본문 요약을 불러오지 못해 이전 결과를 표시합니다.';}
}
function fileEntry(f){
 const url=safeURL(f.web_url),summary=summaryForFile(f,state.fileSummaries);
 const label=summary.status==='ok'?'본문 요약':summary.status==='partial'?'일부 본문 요약':'';
 const body=`<span class="file-icon ${fileKind(f.name).toLowerCase()}">${fileKind(f.name)}</span><span class="file-info"><strong>${esc(f.name)}</strong><span class="file-meta"><b class="${f.change_kind==='created'?'file-new':''}">${f.change_kind==='created'?'신규':'수정'}</b> ${kstTime(f.changed_at)}${url?' ↗':''}</span><span class="file-summary ${label?'has-summary':'summary-pending'}" title="${esc(summary.detail)}">${label?`<em>${label}</em>`:''}${esc(summary.text)}</span><small title="${esc(f.folder_path)}">${esc(f.folder_path.split('/').filter(Boolean).slice(-2).join(' / '))}</small></span>`;
 return `<article class="file-card">${url?`<a class="file-entry" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${body}</a>`:`<div class="file-entry">${body}</div>`}${label?infoButton('file-summary:'+f.item_id,f.name,summary.text+'\n\n'+summary.detail+'\n본문 확인 '+kstTime(summary.checkedAt),'요약 전체'):''}</article>`;
}
function filesWidget(){
 const files=recentFiles(state.files),run=state.fileRuns[0],bad=state.fileError||run?.status==='failed';
 const count=files.filter(f=>['ok','partial'].includes(summaryForFile(f,state.fileSummaries).status)).length;
 return `<section class="panel files-panel paged-panel" aria-label="OneDrive 최근 자료"><div class="panel-head"><div><h2>OneDrive 최근 자료</h2><small>최근 7일 · ${files.length}개 · 본문 요약 ${count}개</small></div><span class="cloud-mark" aria-hidden="true">☁</span></div>${bad?`<p class="widget-alert">${esc(state.fileError||'최근 조회 실패 · 이전 목록입니다.')}</p>`:''}${state.summaryError?`<p class="widget-alert">${esc(state.summaryError)}</p>`:''}${pageList(files,'files',fileEntry,180,run&&run.status!=='failed'?'최근 변경 파일이 없습니다.':'아직 확인된 파일이 없습니다.')}<div class="file-check"><span>${run?'확인 '+kstTime(run.checked_at):'조회 대기'}${run?.status==='partial'?' · 일부 범위':''}</span>${infoButton('file-scope','OneDrive 확인 범위',(run?.detail||'다음 업무보드 원본 조회 때 OneDrive 변경 목록을 수집합니다.')+'\n\n요약은 실제 읽은 본문의 요지입니다. 파일이 수정되면 다시 확인하기 전까지 이전 요약을 표시하지 않습니다. 읽지 않은 파일은 요약 대기로 구분합니다.\n파일별 최신 생성·변경을 표시하며 삭제·모든 중간 저장을 추적하는 감사 로그는 아닙니다.','범위')}</div></section>`;
}

function toast(s){$('#toast').textContent=s;$('#toast').className='show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',4500);}
function errorMessage(e){const s=e.message||String(e);return /Failed to fetch|fetch failed|NetworkError/.test(s)?'연결되지 않아 저장하지 못했습니다. 입력 내용은 이 창에 남아 있습니다. 인터넷 연결 후 다시 저장하세요.':s;}
async function rows(table,configure=q=>q){let result=[];for(let from=0;;from+=1000){const {data,error}=await configure(db.from(table).select('*')).range(from,from+999);if(error)throw error;result.push(...data);if(data.length<1000)return result;}}
async function loadHistory(){if(demo)return;const [start,end]=monthBounds(state.month);state.history=await rows('task_history',q=>q.eq('workspace_id',state.workspace.id).gte('occurred_at',start+'T00:00:00+09:00').lt('occurred_at',end+'T00:00:00+09:00').order('occurred_at',{ascending:false}).order('id',{ascending:false}));}
async function refresh(silent=false){if(!state.workspace||state.loading)return;state.loading=true;const seq=++loadSeq;try{
 if(!demo){const [tasks,events,runs,links,messages,overrides]=await Promise.all([rows('tasks',q=>q.eq('workspace_id',state.workspace.id).order('id')),rows('calendar_events',q=>q.eq('workspace_id',state.workspace.id).order('start_at')),db.from('sync_runs').select('*').eq('workspace_id',state.workspace.id).order('generated_at',{ascending:false}).limit(20),rows('workspace_links',q=>q.eq('workspace_id',state.workspace.id).order('sort_order')),rows('workdesk_messages',q=>q.eq('workspace_id',state.workspace.id).order('created_at').order('id')),rows('calendar_overrides',q=>q.eq('workspace_id',state.workspace.id).order('event_id'))]);if(runs.error)throw runs.error;if(seq!==loadSeq)return;Object.assign(state,{tasks,sourceEvents:events,events:mergeCalendarOverrides(events,overrides),runs:runs.data,links,messages,overrides});await Promise.all([loadHistory(),loadFiles(),loadFileSummaries()]);}
 state.synced=new Date().toISOString();state.error='';render();refreshConversation();void updateWeather();if(!silent)toast(demo?'예시 화면을 갱신했습니다.':'저장된 최신 상태를 불러왔습니다.');
 }catch(e){state.error=errorMessage(e);render();}finally{state.loading=false;}}
function subscribe(){if(demo)return;channel=db.channel('workdesk:'+state.workspace.id);for(const table of ['tasks','task_history','calendar_events','sync_runs','workdesk_messages','calendar_overrides','file_changes','file_sync_runs','file_summaries'])channel.on('postgres_changes',{event:'*',schema:'public',table,filter:'workspace_id=eq.'+state.workspace.id},()=>{clearTimeout(reloadTimer);reloadTimer=setTimeout(()=>refresh(true),250);});channel.subscribe(status=>{state.realtime=status==='SUBSCRIBED';const n=$('#liveStatus');if(n)n.innerHTML=syncLabel();});}
const syncLabel=()=>`${state.realtime?'<i class="sync-dot"></i>보드 실시간 연결':'<i class="sync-dot warn"></i>보드 주기적 동기화'}<br><small>화면 확인 ${kstTime(state.synced)}</small>`;
function login(message=''){
 if(!LOGIN_CONFIGURED&&!message)message='첫 로그인 연결 설정을 마무리하고 있습니다. 설정 완료 후 이메일로 접속할 수 있습니다.';
 app.innerHTML=`<div class="login-wrap"><section class="login-story"><div class="brand"><span class="mark">d.</span><span>다한닷<small>PERSONAL WORKDESK</small></span></div><div class="eyebrow">YOUR WORK, IN ONE PLACE</div><h1>내 업무의 흐름을<br>한곳에 남기다.</h1><p>메일과 대화 속 해야 할 일부터<br>오늘의 진척, 작은 메모, 완료의 기록까지.<br>어디서든 같은 업무보드로 이어집니다.</p><div class="story-line">업무 관리 &nbsp; / &nbsp; 일정과 이력 &nbsp; / &nbsp; 다한닷 연동</div></section><section class="login-panel"><div class="login-card"><h2>나의 업무보드</h2><p>등록된 이메일로 로그인하세요.<br>개인 업무와 기록은 본인만 볼 수 있습니다.</p><form id="loginForm"><label for="email">이메일 주소</label><input type="email" id="email" required autocomplete="email" placeholder="회사 이메일 주소"><button class="btn primary" type="submit" ${LOGIN_CONFIGURED?'':'disabled'}>로그인 링크 받기 →</button></form><div id="loginMessage" class="error" role="status">${esc(message)}</div><details><summary>이메일에 인증번호가 표시되는 경우</summary><form id="otpForm"><input id="otp" autocomplete="one-time-code" inputmode="numeric" placeholder="인증번호"><button class="btn" type="submit">인증번호로 로그인</button></form></details><p class="muted" style="margin-top:30px">PC와 휴대폰에서 같은 계정을 사용하세요.<br>갤럭시에서는 브라우저의 ‘홈 화면에 추가’로 빠르게 열 수 있습니다.</p></div></section></div>`;
 $('#loginForm').onsubmit=async e=>{e.preventDefault();if(!LOGIN_CONFIGURED)return;const btn=e.submitter;btn.disabled=true;$('#loginMessage').textContent='로그인 메일을 요청하고 있습니다…';try{const {error}=await db.auth.signInWithOtp({email:$('#email').value.trim(),options:{emailRedirectTo:location.origin+location.pathname,shouldCreateUser:true}});if(error)throw error;$('#loginMessage').textContent='로그인 링크를 보냈습니다. 받은 메일에서 링크를 열어주세요. 메일이 없으면 스팸함을 확인하세요.';}catch(e){$('#loginMessage').textContent=errorMessage(e);}finally{btn.disabled=false;}};
 $('#otpForm').onsubmit=async e=>{e.preventDefault();if(!LOGIN_CONFIGURED)return;e.submitter.disabled=true;try{const {error}=await db.auth.verifyOtp({email:$('#email').value.trim(),token:$('#otp').value.trim(),type:'email'});if(error)throw error;}catch(e){$('#loginMessage').textContent=errorMessage(e);}finally{e.submitter.disabled=false;}};
}
async function start(user){if(state.workspace||starting)return;starting=true;state.user=user;try{const {data,error}=await db.from('workspaces').select('*');if(error)throw error;if(!data.length){await db.auth.signOut();login('이 계정에 연결된 업무보드가 없습니다. 등록된 이메일로 로그인하세요.');return;}state.workspace=data[0];await refresh(true);subscribe();}catch(e){login(errorMessage(e));}finally{starting=false;}}
function taskCard(t){const pending=messagesForTarget(state.messages,{task_id:t.id}).filter(m=>m.resolution_status==='pending').length;return `<article class="task-card"><span class="task-state-dot ${t.status==='done'?'done':''}" aria-hidden="true">${t.status==='done'?'✓':t.status==='partial'?'◐':'◌'}</span><button class="task-open" data-task="${esc(t.id)}"><div class="task-title">${esc(t.title)}</div><div class="task-meta">${statusBadge(t.status)}${pending?`<span class="badge review">대화 확인 대기 ${pending}</span>`:''}${t.pending_review?'<span class="badge review">원본 변경</span>':''}<span>${esc(t.project)}</span>${t.due_date?`<span>마감 ${dateLabel(t.due_date)}</span>`:''}${t.next_review_on?`<span>다음 확인 ${dateLabel(t.next_review_on)}</span>`:''}</div>${t.remaining_action&&t.status!=='done'?`<p class="task-note remaining">남은 일 · ${esc(t.remaining_action)}</p>`:t.next_action&&t.status!=='done'?`<p class="task-note">${esc(t.next_action)}</p>`:''}${t.note?`<p class="task-note">${esc(t.note.slice(0,110))}${t.note.length>110?'…':''}</p>`:''}</button><span class="chevron">›</span></article>`;}
function agenda(events){return events.filter(e=>!e.excluded).map(e=>`<div class="agenda-item"><small>${e.all_day?`${dateLabel(e.start_at)} · 종일`:kstTime(e.start_at)}${e.personal_changed?' · 내 일정 조정':''}${e.status==='tentative'?' · 참석 확인 필요':''}</small><strong>${esc(e.title)}</strong>${link(e.url,'일정 원문')}<p class="muted">${esc(e.personal_note||e.note||'')}</p><button class="text-btn event-converse" data-event="${esc(e.id)}">이 일정에 대해 이야기하기 →</button></div>`).join('')||empty('등록된 일정이 없습니다.');}
function historyList(items){return `<div class="timeline">${items.map(h=>`<div class="timeline-item"><button data-history="${esc(h.id)}"><small>${kstTime(h.occurred_at)} · ${esc(h.actor)} · ${esc(h.action)}</small><strong>${esc(h.after_data.title)}</strong><p>${h.before_data?`${esc(statuses[h.before_data.status])} → `:''}${esc(statuses[h.after_data.status])}${h.after_data.note?` · ${esc(h.after_data.note.slice(0,130))}`:''}</p></button></div>`).join('')}</div>`;}
function calendarView(){
 const start=state.month+'-01',offset=new Date(start+'T00:00:00Z').getUTCDay(),first=addDays(start,-offset);
 const cells=Array.from({length:42},(_,i)=>{const d=addDays(first,i),count=state.tasks.filter(t=>!t.archived&&(t.due_date===d||t.next_review_on===d)).length,activity=state.history.filter(h=>day(h.occurred_at)===d).length+state.messages.filter(m=>day(m.created_at)===d).length,events=state.events.filter(e=>eventOnDay(e,d)).length;return `<button class="day ${d.slice(0,7)!==state.month?'outside':''} ${d===state.selected?'selected':''} ${d===day()?'today':''}" data-day="${d}" aria-label="${dateLabel(d)} 업무 ${count}건 일정 ${events}건 기록 ${activity}건"><b>${+d.slice(8)}</b><span class="day-count">${count?`업 ${count} `:''}${events?`일 ${events}`:''}${activity?`<br>기록 ${activity}`:''}</span></button>`;}).join('');
 const records=[...state.events.filter(e=>eventOnDay(e,state.selected)).map(data=>({kind:'event',data})),...state.tasks.filter(t=>!t.archived&&(t.due_date===state.selected||t.next_review_on===state.selected)).map(data=>({kind:'task',data})),...state.history.filter(h=>day(h.occurred_at)===state.selected).map(data=>({kind:'history',data})),...state.messages.filter(m=>day(m.created_at)===state.selected).map(data=>({kind:'message',data}))];
 return `<div class="calendar-layout" data-calendar-pane="${state.calendarPane}"><section class="panel month-panel"><div class="panel-head"><h2>${state.month.replace('-','년 ')}월</h2><div class="calendar-tools"><button class="icon-btn" id="prevMonth" aria-label="이전 달">‹</button><button class="btn" id="calendarToday">오늘</button><button class="icon-btn" id="nextMonth" aria-label="다음 달">›</button></div></div><div class="calendar-grid">${['일','월','화','수','목','금','토'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells}</div><div class="calendar-legend">업: 마감·다음 확인 / 일: 일정 / 기록: 대화·진척·완료</div><button class="panel-link day-record-button" data-calendar-pane="day">${dateLabel(state.selected)} 기록 보기 →</button></section><section class="panel paged-panel day-panel"><div class="panel-head"><h2>${dateLabel(state.selected)}</h2><button class="text-btn day-record-button" data-calendar-pane="month">달력으로</button></div>${pageList(records,'day',r=>r.kind==='event'?agenda([r.data]):r.kind==='task'?taskCard(r.data):r.kind==='history'?historyList([r.data]):messageCard(r.data),120,'이날의 업무·일정·처리 기록이 없습니다.')}</section></div>`;
}

function connectView(){
 const latest=state.runs[0],sections=[
 ['업무 상태와 대화','저장한 대화·완료·메모는 기기 간 동기화됩니다. 다한닷은 다음 정기 갱신 또는 ChatGPT에서 “업무보드 대화 반영해줘”라고 요청할 때 대화를 읽고 상태·남은 일·다음 확인일을 정리합니다. 즉시 AI 답변 기능은 연결되어 있지 않습니다.'],
 ['두레이 즐겨찾기 · 한 달 일정','대화방은 갱신 때마다 두레이 즐겨찾기 목록을 다시 확인합니다. 고정 대화방 목록은 사용하지 않습니다. 두레이·Google 일정은 오늘부터 30일을 조회하고, 주간업무보고는 전주 실시 / 금주 예정으로 작성합니다. 즐겨찾기를 해제한 방의 기존 실제 업무·이력은 보존됩니다.'],
 ['원본 조회 시간','평일 오후 1시에 원본을 조회합니다(한국 공휴일 제외). 오전에는 두레이 로그인 후 ChatGPT에서 “업무보드 갱신해줘”라고 요청하세요. 로그인 순간을 자동 감지하는 연결은 아직 없습니다. 상태 새로고침은 이미 수집된 자료와 저장 상태를 불러옵니다.'],
 ['완료 · 부분 완료 · 일정 변경','“끝났어”, “답변만 기다려”, “이번 일정은 빼줘”처럼 이야기하세요. 완료한 일은 일반 안내에서 제외합니다. 날짜를 누르면 당시 메모와 완료 이력을 볼 수 있습니다. 일정 변경·제외는 이 보드의 개인 표시 기준이며 원본 일정이나 타인 초대를 자동 변경하지 않습니다.'],
 ['OneDrive · 주간보고 · 날씨','최근 파일과 주간보고는 OneDrive 원본 링크로 열립니다. 보고서 복사본을 보드에 저장하지 않습니다. 날씨는 천안·서울 오늘/내일 예보이며 화살표·지역 버튼·좌우 밀기로 전환합니다. 예보는 화면을 열 때와 최대 30분 간격으로 확인합니다.'],
 ...(latest?.sources||[]).map(x=>[x.name,`${{ok:'확인',partial:'일부 확인',failed:'실패',not_checked:'미조회'}[x.status]||x.status} · ${kstTime(x.checked_at)}\n${x.detail}`]),
 ...state.events.filter(e=>e.excluded).map(e=>['제외한 일정 · '+e.title,e.personal_note||'개인 업무보드에서 제외했습니다.'])];
 return `<section class="panel paged-panel"><div class="panel-head"><h2>연결 · 사용 안내</h2><div><button class="text-btn" id="exportBtn">백업</button><button class="text-btn" data-logout>로그아웃</button></div></div>${pageList(sections,'guide',([title,body],i)=>`<article class="guide-card"><h3>${esc(title)}</h3><p>${esc(body)}</p>${infoButton('guide:'+title,title,body)}</article>`,156)}</section>`;
}

function bodyView(){
 if(state.view==='conversation')return conversationView();if(state.view==='calendar')return calendarView();if(state.view==='connect')return connectView();
 if(state.view==='history')return `<section class="panel paged-panel"><div class="panel-head"><h2>업무 변경 이력</h2><input id="historyMonth" aria-label="조회 월" type="month" value="${state.month}"></div>${pageList(state.history,'history',h=>historyList([h]),120,'이달의 기록이 없습니다.')}</section>`;
 if(state.view==='links')return `<section class="panel paged-panel"><div class="panel-head"><h2>업무 바로가기</h2><small>원본으로 이동</small></div>${pageList(state.links,'links',l=>`<a class="link-card" href="${esc(safeURL(l.url))}" target="_blank" rel="noopener noreferrer"><strong>${esc(l.label)} ↗</strong><span>${esc(l.description)}</span></a>`,95)}</section>`;
 const tasks=state.tasks.filter(t=>matchesTask(t,state.view,state.query)&&(!state.project||t.project===state.project)&&(!state.status||t.status===state.status)).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||(a.next_review_on||a.due_date||'9999').localeCompare(b.next_review_on||b.due_date||'9999')||['high','normal','low'].indexOf(a.priority)-['high','normal','low'].indexOf(b.priority));
 const projects=Object.fromEntries([...new Set(state.tasks.map(t=>t.project))].sort().map(x=>[x,x]));
 return `<section class="panel paged-panel"><div class="panel-head"><h2>업무 목록</h2><small>${tasks.length}건</small></div><div class="filters"><input id="search" aria-label="업무 검색" placeholder="업무 · 메모 검색" value="${esc(state.query)}"><select id="projectFilter" aria-label="프로젝트"><option value="">모든 프로젝트</option>${options(projects,state.project)}</select><select id="statusFilter" aria-label="상태"><option value="">모든 상태</option>${options(statuses,state.status)}</select></div>${pageList(tasks,'tasks',taskCard,compact()?106:124,'이곳에서 챙길 업무가 없습니다. 필요한 일을 대화로 남겨주세요.')}</section>`;
}
function agendaPanel(){const events=upcomingEvents(state.events);return `<section class="panel paged-panel agenda-panel"><div class="panel-head"><div><h2>다가오는 일정</h2><small>앞으로 30일 · ${events.length}건</small></div><button class="text-btn" data-view="calendar">달력 ↗</button></div>${pageList(events,'agenda',e=>agenda([e]),140,'앞으로 30일 내 등록된 일정이 없습니다.')}<div class="file-check">${dateLabel(day())} ~ ${dateLabel(addDays(day(),29))}</div></section>`;}

function briefingWidget(){
 const latest=state.runs[0],text=latest&&state.tasks.some(t=>Date.parse(t.updated_at)>Date.parse(latest.imported_at||latest.generated_at))?currentBriefing(state.tasks,state.events):latest?.summary||'필요한 일을 대화로 남겨주세요. 수집한 업무와 일정은 이곳에서 확인합니다.';
 const lines=text.split(/\n+/).map(x=>x.trim()).filter(Boolean);
 return `<section class="briefing briefing-expanded" aria-label="오늘의 주요 내용"><span class="briefing-icon">✦</span><div><div class="briefing-heading"><b>오늘의 주요 내용</b><small>${latest?'원본 조회 '+kstTime(latest.generated_at):''}</small></div><ul>${lines.map(line=>`<li>${esc(line)}</li>`).join('')}</ul></div></section>`;
}

const sourceOptions=()=>({error:state.error,online:navigator.onLine,fileError:state.fileError});
const sourceGroups=()=>sourceHealth(state.runs,state.fileRuns,sourceOptions());
const sourceDot=status=>`<i class="source-dot ${status}" aria-hidden="true"></i>`;
function sourceIndicator(){
 const summary=collectionSummary(sourceGroups(),sourceOptions());
 return `<button id="sourceStatusButton" class="source-status-button" popovertarget="sourcePopover" aria-label="자료 수집 상태: ${summary.label}. 상세 열기" aria-expanded="false" title="원본 조회·반영 결과 보기">${sourceDot(summary.status)}<span>${summary.label}</span><span class="status-caret" aria-hidden="true">⌄</span></button><section id="sourcePopover" class="source-popover" popover="auto" aria-label="자료 수집 상태"></section>`;
}
function paintSourcePopup(){
 const popup=$('#sourcePopover');if(!popup)return;
 const groups=sourceGroups(),latest=state.runs[0];
 const selected=groups.find(g=>g.id===state.sourceSelected);
 const detail=selected?.records.map(r=>`${r.name} · ${r.label}\n확인 ${kstTime(r.checkedAt)}${r.lastSuccess&&r.status!=='ok'?' · 마지막 성공 '+kstTime(r.lastSuccess):''}\n${r.detail}`).join('\n\n')||'';
 const chunks=detail.match(/[\s\S]{1,180}/g)||[''];const detailPage=Math.min(state.sourceDetailPage,chunks.length-1);
 popup.innerHTML=`<div class="source-popup-head"><div><strong>자료 수집 상태</strong><small>${demo?'예시 결과':latest?'수집 '+kstTime(latest.generated_at):'아직 수집 기록이 없습니다'}</small></div><button class="source-close" popovertarget="sourcePopover" popovertargetaction="hide" aria-label="수집 상태 닫기">×</button></div>${state.error||!navigator.onLine?'<p class="source-popup-warning">보드 연결을 확인하지 못해 이전 결과를 표시합니다.</p>':''}<div class="source-rows">${groups.map(g=>`<button class="source-row ${selected?.id===g.id?'selected':''}" data-source="${g.id}" aria-expanded="${selected?.id===g.id}">${sourceDot(g.status)}<span>${g.name}</span><b>${g.label}</b><span aria-hidden="true">›</span></button>`).join('')}</div>${selected?`<div class="source-detail"><p>${esc(chunks[detailPage])}</p>${chunks.length>1?`<div class="source-detail-pages"><button data-source-page="${detailPage-1}" ${detailPage===0?'disabled':''} aria-label="이전 상세">‹</button><small>${detailPage+1} / ${chunks.length}</small><button data-source-page="${detailPage+1}" ${detailPage===chunks.length-1?'disabled':''} aria-label="다음 상세">›</button></div>`:''}</div>`:'<p class="source-popup-hint">항목을 누르면 확인 시각과 누락 이유가 나옵니다.</p>'}<div class="source-legend">${[['ok','성공'],['partial','일부'],['failed','실패'],['not_checked','미조회']].map(([s,l])=>`<span>${sourceDot(s)}${l}</span>`).join('')}</div><p class="source-popup-foot">저장된 원본 조회 결과입니다. 보드 실시간 연결과는 별개입니다.</p>`;
 popup.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{state.sourceSelected=state.sourceSelected===b.dataset.source?null:b.dataset.source;state.sourceDetailPage=0;paintSourcePopup();popup.querySelector(`[data-source="${b.dataset.source}"]`)?.focus();});
 popup.querySelectorAll('[data-source-page]').forEach(b=>b.onclick=()=>{state.sourceDetailPage=+b.dataset.sourcePage;paintSourcePopup();});
}
function bindSourcePopup(open=false){
 const popup=$('#sourcePopover'),button=$('#sourceStatusButton');paintSourcePopup();
 const position=()=>{const r=button.getBoundingClientRect();popup.style.left=Math.max(8,Math.min(innerWidth-368,r.right-360))+'px';popup.style.top=Math.min(r.bottom+8,innerHeight-100)+'px';};
 popup.addEventListener('beforetoggle',e=>{if(e.newState==='open')position();});
 popup.addEventListener('toggle',e=>button.setAttribute('aria-expanded',String(e.newState==='open')));
 if(open)popup.showPopover();
}
function scenicBanner(){return `<figure class="scenic-banner ${sceneryPaused?'paused':''}" aria-label="AI로 만든 수변 도시 파노라마"><img src="${sceneryURL}" alt="밝은 푸른 하늘과 잔잔한 수면 위로 펼쳐진 가상의 도시 스카이라인" width="2172" height="724" decoding="async"><figcaption><span class="scenery-credit" title="AI로 만든 가상의 수변 도시 풍경">CITY AT EASE <span>· AI 파노라마</span></span><button id="sceneryToggle" aria-label="풍경 움직임 ${sceneryPaused?'재생':'멈춤'}" aria-pressed="${sceneryPaused}">${sceneryPaused?'▷':'Ⅱ'}</button></figcaption></figure>`;}

// Keep the decoded image and both animation playheads through board refreshes.
function captureScenery(){
 const node=$('.scenic-banner'),image=node?.querySelector('img');
 return {node,times:new Map((image?.getAnimations()||[]).map(a=>[a.animationName,a.currentTime]))};
}
function restoreScenery({node,times}){
 if(!node)return;
 $('.scenic-banner').replaceWith(node);
 for(const animation of node.querySelector('img').getAnimations()){
  const time=times.get(animation.animationName);
  if(Number.isFinite(time))animation.currentTime=time;
 }
}

function statsWidget(){return `<div class="stats">${[['today','오늘',state.tasks.filter(t=>needsAttention(t)).length],['review','확인',state.tasks.filter(t=>!t.archived&&(t.status==='review'||t.pending_review)).length],['partial','부분 완료',state.tasks.filter(t=>!t.archived&&t.status==='partial').length],['done','완료',state.tasks.filter(t=>!t.archived&&t.status==='done').length]].map(([k,l,n])=>`<button class="stat" data-view="${k}"><small>${l}</small><strong>${n}</strong></button>`).join('')}</div>`;}
function boardLayout(isWork){
 const weather=`<section id="weatherWidget" class="panel weather-panel" aria-label="천안과 서울 오늘 내일 날씨">${weatherWidget()}</section>`;
 if(isWork)return `<div class="board-grid dashboard-grid" data-mobile-panel="${state.mobilePanel}"><div class="dashboard-overview">${briefingWidget()}${statsWidget()}</div>${weather}<nav class="dashboard-tabs" aria-label="보드 영역">${[['work','업무 목록'],['agenda','다가오는 일정'],['files','최근 자료']].map(([id,label])=>`<button data-mobile-panel="${id}" aria-pressed="${state.mobilePanel===id}">${label}</button>`).join('')}</nav><div id="viewBody" class="dashboard-work">${bodyView()}</div><div class="dashboard-agenda">${agendaPanel()}</div><aside class="dashboard-files">${filesWidget()}</aside></div>`;
 return `<div class="board-grid" data-mobile-panel="${state.mobilePanel}"><div class="board-main"><div id="viewBody">${bodyView()}</div></div><aside class="right-column">${weather}<div class="rail-tabs"><button data-mobile-panel="work" class="mobile-work-tab ${state.mobilePanel==='work'?'active':''}">업무</button><button data-rail="files" class="${(compact()?state.mobilePanel:state.rail)==='files'?'active':''}">최근 자료</button><button data-rail="agenda" class="${(compact()?state.mobilePanel:state.rail)==='agenda'?'active':''}">일정 · 30일</button></div><div class="rail-body">${(compact()?state.mobilePanel:state.rail)==='agenda'?agendaPanel():filesWidget()}</div></aside></div>`;
}
let versionCheckedAt=0;
async function checkForUpdate(force=false){
 if(!force&&Date.now()-versionCheckedAt<300000)return state.updateAvailable;
 versionCheckedAt=Date.now();
 try{const response=await fetch('./version.json',{cache:'no-store'});if(!response.ok)return null;const {version}=await response.json();if(typeof version==='string'&&/^\d+\.\d+\.\d+$/.test(version)&&version.localeCompare(APP_VERSION,undefined,{numeric:true})>0){state.updateAvailable=version;render();return version;}}
 catch{}return null;
}
function applyUpdate(){
 if([...drafts.values()].some(value=>value?.body?.trim())||$('#detail').open||$('#historyDetail').open){toast('작성 중인 대화를 저장하고 열린 창을 닫은 뒤 새 화면을 적용해 주세요.');return;}
 const url=new URL(location.href);url.searchParams.set('v',state.updateAvailable||APP_VERSION);location.assign(url.href);
}
async function manualRefresh(){if(await checkForUpdate(true)){applyUpdate();return;}await refresh();}

function render(){
 if(!state.workspace)return;const scenery=captureScenery();const sourceOpen=$('#sourcePopover')?.matches(':popover-open')||false;infoContent.clear();const v=views[state.view],isWork=['today','all','review','partial','done'].includes(state.view),report=state.links.find(l=>/주간.*업무보고/.test(l.label));
 const brand=`<button class="brand home-button" data-home aria-label="다한닷 홈 · 오늘 챙길 일"><span class="mark">d.</span><span>다한닷<small>나의 업무보드</small></span></button>`;
 app.innerHTML=`<div class="layout"><aside class="sidebar">${brand}<div class="mobile-brand">${brand}<select id="mobileView" aria-label="업무 화면 선택">${Object.entries(views).map(([k,v])=>`<option value="${k}" ${state.view===k?'selected':''}>${v[0]}</option>`).join('')}</select></div><div class="owner">${esc(state.workspace.name)}<small>내 일의 시작과 마무리</small></div><div class="nav-label">MY WORKSPACE</div><nav class="nav">${Object.entries(views).map(([k,v])=>`<button data-view="${k}" class="${state.view===k?'active':''}"><span class="symbol">${v[2]}</span>${v[0]}</button>`).join('')}</nav><div class="sidebar-bottom"><div id="liveStatus">${syncLabel()}</div><button class="text-btn" data-logout>로그아웃</button></div></aside><div class="work-area"><header class="topbar"><span>PERSONAL WORKDESK</span><div class="topbar-actions">${sourceIndicator()}<a class="shortcut chatgpt-shortcut" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer" aria-label="ChatGPT 새 창으로 열기"><img class="brand-icon chatgpt-icon" src="./images/chatgpt.svg" width="22" height="22" alt=""><span>ChatGPT</span></a><a class="shortcut clova-shortcut" href="${esc(safeURL(state.links.find(l=>l.label==='클로바노트')?.url)||CLOVA_URL)}" target="_blank" rel="noopener noreferrer" aria-label="클로바노트 새 창으로 열기"><img class="brand-icon" src="./images/clovanote.svg" width="24" height="24" alt=""><span>클로바노트</span></a>${report?`<a class="shortcut report-shortcut" href="${esc(safeURL(report.url))}" target="_blank" rel="noopener noreferrer">주간보고 ↗</a>`:''}<button id="themeToggle" class="theme-toggle" role="switch" aria-checked="${theme==='dark'}" aria-label="다크모드"><span aria-hidden="true">${theme==='dark'?'☀':'☾'}</span><span class="theme-label">${theme==='dark'?'라이트':'다크'}</span></button><small class="today-label">${dateLabel(day())}</small></div></header><main class="main">${demo?'<div class="notice demo-notice">예시 화면 · 실제 업무와 연결되지 않습니다.</div>':''}${state.error?`<div class="notice error" role="alert">${esc(state.error)}</div>`:''}${state.updateAvailable?'<div class="notice update-notice">새 화면이 준비되었습니다. <button class="text-btn" id="applyUpdate">새 화면 적용 ↻</button></div>':''}${!navigator.onLine?'<div class="notice offline">오프라인 · 인터넷 연결 후 저장하세요.</div>':''}<div class="title-row"><div class="title-copy"><p class="eyebrow">MY WORK, MY PACE</p><h1>${v[0]}</h1><p class="sub">${v[1]}</p></div>${scenicBanner()}<div class="actions"><button class="btn" id="refreshBtn" aria-label="상태 새로고침">⟳ <span>새로고침</span></button><button class="btn primary" id="addBtn">＋ <span>대화로 남기기</span></button></div></div>${boardLayout(isWork)}<footer><span>다한닷 · v${APP_VERSION}</span><span>두레이 즐겨찾기 · 일정 30일</span></footer></main></div></div>`;restoreScenery(scenery);bind();bindSourcePopup(sourceOpen);
}

async function changeMonth(month){state.pages.day=0;state.pages.history=0;state.month=month;state.selected=month===day().slice(0,7)?day():month+'-01';try{await loadHistory();render();}catch(e){toast(errorMessage(e));}}
function navigate(view){state.view=view;state.query='';state.status='';state.project='';state.pages={};state.mobilePanel='work';render();}
function bind(){
 app.querySelectorAll('[data-view]').forEach(n=>n.onclick=()=>navigate(n.dataset.view));app.querySelectorAll('[data-home]').forEach(n=>n.onclick=async()=>{state.month=day().slice(0,7);state.selected=day();state.calendarPane='month';state.weatherCity=0;state.rail='files';navigate('today');try{await loadHistory();}catch(e){toast(errorMessage(e));}});
 $('#mobileView').onchange=e=>navigate(e.target.value);app.querySelectorAll('[data-logout]').forEach(n=>n.onclick=logout);
 $('#themeToggle').onclick=()=>{theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('dahandot-theme',theme);}catch{}render();};
 app.querySelectorAll('[data-rail]').forEach(b=>b.onclick=()=>{state.rail=b.dataset.rail;state.mobilePanel=b.dataset.rail;render();});app.querySelectorAll('[data-mobile-panel]').forEach(b=>{if(b.tagName==='BUTTON')b.onclick=()=>{state.mobilePanel=b.dataset.mobilePanel;render();};});
 app.querySelectorAll('button[data-calendar-pane]').forEach(b=>b.onclick=()=>{state.calendarPane=b.dataset.calendarPane;render();});
 app.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>showInfo(b.dataset.info));
 $('#sceneryToggle').onclick=()=>{sceneryPaused=!sceneryPaused;try{localStorage.setItem('dahandot-scenery-paused',String(sceneryPaused));}catch{}const banner=$('.scenic-banner');banner.classList.toggle('paused',sceneryPaused);$('#sceneryToggle').textContent=sceneryPaused?'▷':'Ⅱ';$('#sceneryToggle').setAttribute('aria-pressed',String(sceneryPaused));$('#sceneryToggle').setAttribute('aria-label','풍경 움직임 '+(sceneryPaused?'재생':'멈춤'));};
 $('#refreshBtn').onclick=manualRefresh;if($('#applyUpdate'))$('#applyUpdate').onclick=applyUpdate;$('#addBtn').onclick=()=>openConversation({});bindWeather();bindItems(app);bindPaging();
 if($('#search')){const applySearch=e=>{if(e.isComposing)return;clearTimeout(searchTimer);const input=e.target;searchTimer=setTimeout(()=>{state.query=input.value;state.pages.tasks=0;const pos=input.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);},180);};$('#search').oninput=applySearch;$('#search').oncompositionend=applySearch;$('#projectFilter').onchange=e=>{state.project=e.target.value;state.pages.tasks=0;render();};$('#statusFilter').onchange=e=>{state.status=e.target.value;state.pages.tasks=0;render();};}
 if($('#prevMonth')){$('#prevMonth').onclick=()=>changeMonth(addDays(state.month+'-01',-1).slice(0,7));$('#nextMonth').onclick=()=>changeMonth(monthBounds(state.month)[1].slice(0,7));$('#calendarToday').onclick=()=>changeMonth(day().slice(0,7));app.querySelectorAll('[data-day]').forEach(n=>n.onclick=async()=>{const d=n.dataset.day;if(d.slice(0,7)!==state.month){state.month=d.slice(0,7);await loadHistory();}state.selected=d;state.pages.day=0;state.calendarPane='day';render();});}
 if($('#historyMonth'))$('#historyMonth').onchange=e=>{if(e.target.value)changeMonth(e.target.value);};if($('#exportBtn'))$('#exportBtn').onclick=exportBackup;
}

function bindItems(root){root.querySelectorAll('[data-task]').forEach(n=>n.onclick=()=>openTask(state.tasks.find(t=>t.id===n.dataset.task)));root.querySelectorAll('[data-event]').forEach(n=>n.onclick=()=>openConversation({event_id:n.dataset.event}));root.querySelectorAll('[data-converse]').forEach(n=>n.onclick=()=>openConversation({}));root.querySelectorAll('[data-message]').forEach(n=>n.onclick=()=>{const m=state.messages.find(x=>x.id===n.dataset.message);if(m)openConversation({task_id:m.task_id,event_id:m.event_id}).then(()=>{threadPage=messagesForTarget(state.messages,conversationTarget).findIndex(x=>x.id===m.id);refreshConversation();});});root.querySelectorAll('[data-history]').forEach(n=>n.onclick=()=>showHistory([...state.history,...detailHistory].find(h=>String(h.id)===n.dataset.history)));}
function conversationList(messages,compact=false){if(!messages.length)return `<div class="conversation-empty"><span>◌</span><strong>어디까지 진행하셨나요?</strong><p>처리한 일, 남은 일, 바뀐 생각을<br>평소 이야기하듯 남겨주세요.</p></div>`;return `<div class="conversation-list ${compact?'compact':''}">${[...messages].sort((a,b)=>a.created_at.localeCompare(b.created_at)||a.id.localeCompare(b.id)).map(m=>`<article class="conversation-turn"><div class="message-meta"><span>나 · ${kstTime(m.created_at)}</span><span class="message-state ${m.resolution_status}">${esc(messageStatuses[m.resolution_status]||m.resolution_status)}</span></div>${compact?`<button class="message-context" data-message="${esc(m.id)}">${esc(state.tasks.find(t=>t.id===m.task_id)?.title||state.events.find(e=>e.id===m.event_id)?.title||'자유롭게 남긴 이야기')} ↗</button>`:''}<div class="message-bubble user-message">${esc(m.body)}</div>${m.reply?`<div class="assistant-label"><span class="tiny-mark">d.</span>다한닷 <small>${kstTime(m.resolved_at)}</small></div><div class="message-bubble assistant-message">${esc(m.reply)}</div>`:'<p class="pending-caption">저장됐습니다. 다음 갱신 때 다한닷이 확인합니다.</p>'}</article>`).join('')}</div>`;}
function messageCard(m){return `<article class="message-card"><small>${kstTime(m.created_at)} · ${esc(messageStatuses[m.resolution_status])}</small><button data-message="${esc(m.id)}"><strong>${esc(state.tasks.find(t=>t.id===m.task_id)?.title||state.events.find(e=>e.id===m.event_id)?.title||'자유롭게 남긴 이야기')}</strong><p>${esc(m.body)}</p><span>${esc(m.reply||'다한닷 확인 대기')}</span><b class="message-read">대화 전체 보기 →</b></button></article>`;}
function conversationView(){const pending=state.messages.filter(m=>m.resolution_status==='pending').length;return `<section class="panel paged-panel conversation-feed"><div class="panel-head"><h2>나눈 이야기</h2><span class="badge ${pending?'review':''}">${pending?`확인 대기 ${pending}건`:'모든 대화 확인'}</span></div><p class="conversation-page-note">진척과 생각을 편하게 남기세요. 다한닷이 후속 일을 정리합니다.</p>${pageList([...state.messages].reverse(),'messages',messageCard,180,'아직 나눈 이야기가 없습니다. 대화로 남기기를 눌러주세요.')}</section>`;}

function contextSummary(){const t=state.tasks.find(t=>t.id===conversationTarget.task_id),e=state.events.find(e=>e.id===conversationTarget.event_id);if(t)return `<section class="conversation-context"><div class="task-meta">${statusBadge(t.status)}${t.archived?'<span class="badge">보관됨</span>':''}${t.next_review_on?`<span>다음 확인 ${dateLabel(t.next_review_on)}</span>`:''}${t.due_date?`<span>마감 ${dateLabel(t.due_date)}</span>`:''}</div><h3>${esc(t.title)}</h3>${t.remaining_action?`<p>남은 일 · ${esc(t.remaining_action)}</p>`:''}<small>현재 반영된 내용입니다. 새로 남긴 이야기는 확인 후 바뀝니다.</small></section>`;if(e)return `<section class="conversation-context"><div class="task-meta"><span>${e.excluded?'내 업무보드에서 제외됨':e.all_day?dateLabel(e.start_at)+' · 종일':kstTime(e.start_at)}</span></div><h3>${esc(e.title)}</h3>${e.personal_note?`<p>${esc(e.personal_note)}</p>`:''}<small>업무보드에 표시할 일정과 준비할 일을 이야기해 주세요.</small></section>`;return '<section class="conversation-context"><h3>어떤 이야기든 편하게 남겨주세요.</h3><p>새로운 업무도, 여러 업무의 진행 상황도 한 번에 적어도 됩니다.</p></section>';}
function threadHTML(){const messages=messagesForTarget(state.messages,conversationTarget),p=paginate(messages,threadPage,1);threadPage=p.page;return conversationList(p.items)+pager('thread',p);}
function bindThread(){const thread=$('#conversationThread');thread?.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{threadPage=+b.dataset.index;refreshConversation();});}
function refreshConversation(){if(!$('#detail').open||!$('#conversationThread'))return;$('#conversationContext').innerHTML=contextSummary();$('#conversationThread').innerHTML=threadHTML();bindThread();}
function renderDetailHistory(){const node=$('#detailHistory');if(!node)return;const p=paginate(detailHistory,detailPage,3);detailPage=p.page;node.innerHTML=historyList(p.items)+pager('detailHistory',p);bindItems(node);node.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{detailPage=+b.dataset.index;renderDetailHistory();});}
async function openTask(task){if(task)await openConversation({task_id:task.id});else await openConversation({});}
async function openConversation(target){conversationTarget={task_id:target.task_id||null,event_id:target.event_id||null};threadPage=Math.max(0,messagesForTarget(state.messages,conversationTarget).length-1);detailPage=0;const key=targetKey(conversationTarget);const task=state.tasks.find(t=>t.id===conversationTarget.task_id),event=state.events.find(e=>e.id===conversationTarget.event_id);editTask=task?structuredClone(task):null;detailHistory=[];const draft=drafts.get(key)||{body:'',id:crypto.randomUUID()};drafts.set(key,draft);
 $('#detail').innerHTML=`<form id="conversationForm"><div class="dialog-head"><div><p class="eyebrow">A CONVERSATION WITH DAHANDOT</p><h2>${task?'업무 이야기':event?'일정 이야기':'다한닷에게 남기기'}</h2></div><button type="button" class="icon-btn" id="closeConversation" aria-label="닫기">×</button></div><div class="dialog-body conversation-body"><div id="conversationContext">${contextSummary()}</div><div id="conversationThread">${threadHTML()}</div>${task||event?`<details class="previous-records"><summary>이전 메모 · 원문 · 변경 이력</summary>${task?.note?`<div class="legacy-note">${esc(task.note)}</div>`:''}${task?.source_refs?.map(r=>`<div class="ref">${link(r.url,r.label)}<p>${esc(r.excerpt)}</p></div>`).join('')||''}${event?link(event.url,'일정 원문'):''}<div id="detailHistory"></div></details>`:''}</div><div class="conversation-compose"><label class="conversation-label" for="conversationText">진행한 내용을 편하게 적어주세요</label><textarea id="conversationText" rows="3" maxlength="12000" required placeholder="자료는 보냈어. 금요일에 답변만 확인하면 돼.">${esc(draft.body)}</textarea><details class="conversation-timing"><summary>저장한 이야기는 언제 반영되나요?</summary><p>대화는 바로 저장됩니다. 다음 정기 갱신 때 다한닷이 읽고 정리합니다. 지금 반영하려면 ChatGPT에서 “업무보드 대화 반영해줘”라고 말씀해 주세요.</p></details><div id="conversationError" class="error" role="alert"></div></div><div class="dialog-foot"><span class="save-caption">${demo?'예시 대화 · 실제 반영 없음':'즉시 저장 · 다음 갱신 때 정리'}</span><span class="spacer"></span><button type="submit" class="btn primary" id="sendConversation">대화 남기기 ↑</button></div></form>`;
 $('#closeConversation').onclick=()=>$('#detail').close();$('#conversationText').oninput=e=>{const previous=drafts.get(key);drafts.set(key,{body:e.target.value,id:previous?.body===e.target.value?previous.id:crypto.randomUUID()});};$('#conversationForm').onsubmit=sendConversation;$('#detail').showModal();bindThread();$('#detail .dialog-body').scrollTop=$('#detail .dialog-body').scrollHeight;
 if(task){try{const id=task.id;detailHistory=demo?state.history.filter(h=>h.task_id===id):await rows('task_history',q=>q.eq('task_id',id).order('occurred_at',{ascending:false}).order('id',{ascending:false}));if(conversationTarget.task_id!==id||!$('#detailHistory'))return;renderDetailHistory();}catch(e){if($('#detailHistory'))$('#detailHistory').textContent='이력을 불러오지 못했습니다: '+errorMessage(e);}}
}
async function sendConversation(e){e.preventDefault();const btn=e.submitter,input=$('#conversationText'),target={...conversationTarget},key=targetKey(target);btn.disabled=true;input.readOnly=true;$('#conversationError').textContent='';try{if(!navigator.onLine)throw Error('인터넷 연결 후 다시 보내주세요. 작성한 내용은 그대로 남아 있습니다.');const body=validateMessage(input.value);const draft=drafts.get(key)||{body,id:crypto.randomUUID()};drafts.set(key,draft);let message;if(demo)message={id:draft.id,task_id:target.task_id,event_id:target.event_id,body,created_at:new Date().toISOString(),resolution_status:'pending',reply:'',changes:[]};else{const {data,error}=await db.rpc('record_workdesk_message',{p_workspace:state.workspace.id,p_id:draft.id,p_body:body,p_task_id:target.task_id,p_event_id:target.event_id});if(error)throw error;message=data;}if(!state.messages.some(m=>m.id===message.id))state.messages.push(message);drafts.delete(key);if(targetKey(conversationTarget)===key){input.value='';drafts.set(key,{body:'',id:crypto.randomUUID()});}threadPage=Math.max(0,messagesForTarget(state.messages,target).length-1);await refresh(true);refreshConversation();toast(demo?'예시 대화를 남겼습니다. 실제 업무는 바뀌지 않습니다.':'대화를 저장했습니다. 다한닷 확인 대기에 등록됐습니다.');}catch(error){if(targetKey(conversationTarget)===key&&$('#conversationError'))$('#conversationError').textContent=errorMessage(error);}finally{btn.disabled=false;input.readOnly=false;}}
function showHistory(h){if(!h)return;const d=h.after_data;$('#historyDetail').innerHTML=`<div class="dialog-head"><h2>당시 업무 기록</h2><button class="icon-btn" id="closeHistory" aria-label="기록 닫기">×</button></div><div class="dialog-body"><p class="muted">${kstTime(h.occurred_at)} · ${esc(h.actor)} · ${esc(h.action)}</p><h2 style="margin:20px 0">${esc(d.title)}</h2>${statusBadge(d.status)}<dl class="snapshot">${[['프로젝트',d.project],['마감일',dateLabel(d.due_date)],['당시 메모',d.note||'없음'],['남은 일',d.remaining_action||'없음'],['다음 확인일',dateLabel(d.next_review_on)],['다음 행동',d.next_action||'없음']].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p class="form-note">이것은 당시의 기록입니다. 현재 업무 상태와 다를 수 있습니다.</p></div><div class="dialog-foot"><button class="btn primary" id="openCurrent">현재 업무 보기</button></div>`;$('#closeHistory').onclick=()=>$('#historyDetail').close();$('#openCurrent').onclick=()=>{$('#historyDetail').close();$('#detail').close();openTask(state.tasks.find(t=>t.id===h.task_id));};$('#historyDetail').showModal();}
async function exportBackup(){try{const history=demo?state.history:await rows('task_history',q=>q.eq('workspace_id',state.workspace.id).order('id'));const blob=new Blob([JSON.stringify({type:'dahandot.cloud-backup',version:2,exported_at:new Date().toISOString(),tasks:state.tasks,history,events:state.sourceEvents.length?state.sourceEvents:state.events,calendar_overrides:state.overrides,messages:state.messages,links:state.links,file_changes:demo?state.files:await rows('file_changes',q=>q.eq('workspace_id',state.workspace.id).order('id')),file_sync_runs:state.fileRuns,file_summaries:state.fileSummaries},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='dahandot-backup-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(errorMessage(e));}}
async function logout(){if(demo){location.href=location.pathname;return;}if(channel)await db.removeChannel(channel);await db.auth.signOut();drafts.clear();conversationTarget={task_id:null,event_id:null};Object.assign(state,{user:null,workspace:null,tasks:[],history:[],events:[],runs:[],links:[],messages:[],overrides:[],sourceEvents:[],files:[],fileRuns:[],fileError:'',fileSummaries:[],summaryError:'',updateAvailable:null});$('#detail').close();$('#historyDetail').close();login();}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{state.pageSizes={};render();},150);});
window.addEventListener('online',()=>refresh(true));window.addEventListener('offline',render);window.addEventListener('focus',()=>{refresh(true);void checkForUpdate();});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){refresh(true);void checkForUpdate();}});setInterval(()=>{if(document.visibilityState==='visible'){refresh(true);void checkForUpdate();}},30000);
